import React, { useState } from 'react';
import { Modal, Tabs, Tab } from 'react-bootstrap';
import { FiArrowUpRight, FiCheck } from 'react-icons/fi';
import ArchitectureFlow from './ArchitectureFlow';
import styles from './Interactions.module.css';

export default function CaseStudyModal({ project, show, onHide }) {
  const [tab, setTab] = useState('problem');
  const resume = project.source === 'Résumé';
  const nodes = project.architecture || project.techStack.slice(0, 4).map(technology => ({ label: technology, detail: `${technology} is part of this project’s technology stack.` }));
  return (
    <Modal show={show} onHide={onHide} onExited={() => setTab('problem')} centered scrollable size="lg" contentClassName={`${styles.scope} ${styles.modalContent}`} aria-labelledby={`case-title-${project.id}`}>
      <Modal.Header closeButton className={styles.modalHeader}>
        <div><p className={styles.eyebrow}>{project.company}</p><Modal.Title id={`case-title-${project.id}`}>{project.title}</Modal.Title></div>
      </Modal.Header>
      <Modal.Body className={styles.modalBody}>
        <Tabs id={`case-tabs-${project.id}`} activeKey={tab} onSelect={setTab} className={styles.caseTabs} mountOnEnter unmountOnExit>
          <Tab eventKey="problem" title="Problem"><h3>What needed to change</h3><p>{project.problem || project.content}</p></Tab>
          <Tab eventKey="contribution" title="My contribution"><h3>What I worked on</h3><p>{project.contribution || project.content}</p><div className={styles.tags}>{project.techStack.map(tool => <span key={tool}>{tool}</span>)}</div></Tab>
          <Tab eventKey="architecture" title="Architecture"><h3>{resume ? 'How the pieces connect' : 'Documented technology stack'}</h3><ArchitectureFlow nodes={nodes} caption={resume ? undefined : 'Technology overview; not a production topology.'} /></Tab>
          <Tab eventKey="outcome" title="Outcome"><h3>What the work delivered</h3>{project.outcomes ? <ul className={styles.outcomes}>{project.outcomes.map(outcome => <li key={outcome}><FiCheck aria-hidden="true" /><span>{outcome}</span></li>)}</ul> : <p>Quantitative outcomes are not available for this project.</p>}</Tab>
        </Tabs>
        {(project.gitHubUrl || project.liveUrl) && <div className={styles.modalActions}>{project.gitHubUrl && <a href={project.gitHubUrl} target="_blank" rel="noopener noreferrer">GitHub repository <FiArrowUpRight aria-hidden="true" /></a>}{project.liveUrl && <a href={project.liveUrl} target="_blank" rel="noopener noreferrer">Live application <FiArrowUpRight aria-hidden="true" /></a>}</div>}
      </Modal.Body>
    </Modal>
  );
}
