import React, { useMemo, useState } from 'react';
import { FiSearch, FiX } from 'react-icons/fi';
import ProjectCard from '../../components/ProjectCard/ProjectCard';
import CaseStudyModal from '../../components/PortfolioInteractions/CaseStudyModal';
import usePortfolioData from '../../hooks/usePortfolioData';
import { filterProjects, getProjectTechnologies, technologyKey } from '../../utils/portfolioEvidence';
import styles from './Projects.module.css';
import interactions from '../../components/PortfolioInteractions/Interactions.module.css';

export default function Projects({ initialSelection = {} }) {
  const { projects, experience } = usePortfolioData();
  const [query, setQuery] = useState('');
  const [technology, setTechnology] = useState(initialSelection.technology || '');
  const [company, setCompany] = useState('');
  const [activeId, setActiveId] = useState(initialSelection.projectId || null);
  const technologies = useMemo(() => {
    const map = new Map();
    projects.forEach(project => getProjectTechnologies(project).forEach(tool => {
      const key = technologyKey(tool);
      if (!map.has(key)) map.set(key, tool);
    }));
    if (technology && !map.has(technologyKey(technology))) map.set(technologyKey(technology), technology);
    return [...map.values()].sort((a, b) => a.localeCompare(b));
  }, [projects, technology]);
  const filtered = filterProjects(projects, { query, technology, company });
  const active = projects.find(project => project.id === activeId);
  const otherCompanies = [...new Map(projects
    .filter(project => !experience.some(job => job.id === project.companyId))
    .map(project => [project.companyId, project.company])).entries()];
  const reset = () => { setQuery(''); setTechnology(''); setCompany(''); };
  return (
    <div className={`${styles.container} ${interactions.scope}`}>
      <header className={styles.headerContainer}><h1 className={styles.headerTitle}>Projects</h1></header>
      <p className={interactions.pageIntro}>Explore the work by technology or company. Each case study separates the problem, my contribution, the architecture, and the outcome.</p>
      <div className={interactions.filters}>
        <label className={interactions.searchField}><span><FiSearch aria-hidden="true" /> Search projects</span><input aria-label="Search projects" type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Try cache, payments, or catalog…" /></label>
        <label><span>Technology</span><select aria-label="Technology" value={technology ? technologyKey(technology) : ''} onChange={event => setTechnology(technologies.find(tool => technologyKey(tool) === event.target.value) || '')}><option value="">All technologies</option>{technologies.map(tool => <option value={technologyKey(tool)} key={technologyKey(tool)}>{tool}</option>)}</select></label>
        <label><span>Company</span><select aria-label="Company" value={company} onChange={event => setCompany(event.target.value)}><option value="">All companies</option>{experience.filter(job => job.description).map(job => <option key={job.id} value={job.id}>{job.organization}</option>)}{otherCompanies.map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></label>
      </div>
      <div className={interactions.filterSummary}><p role="status">Showing <strong>{filtered.length}</strong> of {projects.length} projects{technology ? ` · ${technology}` : ''}</p>{(query || technology || company) && <button onClick={reset}><FiX aria-hidden="true" /> Clear filters</button>}</div>
      {filtered.length ? <div className={styles.projectsGrid}>{filtered.map(project => <ProjectCard key={project.id} project={project} onOpen={setActiveId} onSelectTechnology={setTechnology} />)}</div> : <div className={interactions.emptyState}><h2>No projects match these filters.</h2><p>Try another technology or clear the filters to explore all work.</p><button onClick={reset}>Show all projects <FiX aria-hidden="true" /></button></div>}
      {active && <CaseStudyModal project={active} show onHide={() => setActiveId(null)} />}
    </div>
  );
}
